    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))

    # Locate the two matching colored line segments on opposite grid edges.
    candidates = []
    for color in set(v for row in grid for v in row if v != bg):
        for axis in ("h", "v"):
            if axis == "h":
                for r in (0, h - 1):
                    cols = [c for c in range(w) if grid[r][c] == color]
                    if len(cols) >= 2 and cols == list(range(min(cols), max(cols) + 1)):
                        candidates.append((len(cols), color, axis, r, min(cols), max(cols)))
            else:
                for c in (0, w - 1):
                    rows = [r for r in range(h) if grid[r][c] == color]
                    if len(rows) >= 2 and rows == list(range(min(rows), max(rows) + 1)):
                        candidates.append((len(rows), color, axis, c, min(rows), max(rows)))
    pairs = []
    for a in candidates:
        for b in candidates:
            if a[1] == b[1] and a[2] == b[2] and a[3] != b[3] and a[4:] [0:0] == ():
                pass
    # Pair opposite edges, preferring the strongest matching runs.
    for i, a in enumerate(candidates):
        for b in candidates[i + 1:]:
            if a[1] != b[1] or a[2] != b[2]:
                continue
            if a[2] == "h" and {a[3], b[3]} == {0, h - 1}:
                pairs.append((min(a[0], b[0]), a, b))
            if a[2] == "v" and {a[3], b[3]} == {0, w - 1}:
                pairs.append((min(a[0], b[0]), a, b))
    _, a, b = max(pairs, key=lambda item: item[0])
    # a/b encode the bar's edge coordinate and its span along the edge.
    bars = sorted((a, b), key=lambda x: x[3])
    first, second = bars
    axis, boundary_color = first[2], first[1]
    if axis == "h":
        bar_edges = [first[3], second[3]]
        span_start = [first[4], second[4]]
        span_end = [first[5], second[5]]
    else:
        bar_edges = [first[3], second[3]]
        span_start = [first[4], second[4]]
        span_end = [first[5], second[5]]

    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, boundary_color)]
    for r, c, color in seeds:
        u = c if axis == "h" else r
        # Dots align with one of the bars; use that bar as the source end.
        distances = [0 if span_start[i] <= u <= span_end[i] else min(abs(u-span_start[i]), abs(u-span_end[i])) for i in range(2)]
        src = 0 if distances[0] <= distances[1] else 1
        dst = 1 - src
        mapped = u + span_start[dst] - span_start[src]
        # Copy the dot's coordinate to the opposite bar and fill between bars.
        if axis == "h":
            for rr in range(min(bar_edges), max(bar_edges) + 1):
                if rr not in bar_edges:
                    out[rr][mapped] = color
            # Extend the original dot toward its source horizontal bar.
            edge = bar_edges[src]
            step = 1 if edge < r else -1
            rr = edge + step
            while rr != r:
                out[rr][c] = color
                rr += step
        else:
            for cc in range(min(bar_edges), max(bar_edges) + 1):
                if cc not in bar_edges:
                    out[r][cc] = color
            edge = bar_edges[src]
            step = 1 if edge < c else -1
            cc = edge + step
            while cc != c:
                out[r][cc] = color
                cc += step
        out[r][c] = 4
    return out
